BEGIN;
DO $$
DECLARE admin_user_id bigint; sam_organization_id bigint; property_listing_id bigint;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext('sam-import-19382'));
 IF EXISTS (SELECT 1 FROM listing_sources WHERE upper(reference_code)='3A0708' OR source_url ~ '[?&]id=19382(&|$)' OR source_url LIKE '%keyref=6007623%') OR EXISTS (SELECT 1 FROM listings WHERE public_listing_id='93c08330-cdd1-4be3-81b2-1d81cbb5b092' OR slug='sam-direct-sale-land-motorway-7-bang-phli-noi-3a0708' OR description ILIKE '%3A0708%' OR (abs(latitude-13.625667461799871)<0.0001 AND abs(longitude-100.91426422959044)<0.0001 AND abs(land_area_sqm-19930.4)<1)) THEN
 RAISE NOTICE 'SAM 3A0708 already exists; skipping duplicate import'; RETURN; END IF;
 SELECT id INTO admin_user_id FROM auth_users WHERE lower(email)='mapxprop@gmail.com' AND deleted_at IS NULL ORDER BY id LIMIT 1;
 SELECT id INTO sam_organization_id FROM organizations WHERE slug='sukhumvit-asset-management-sam' AND verification_status='verified' AND is_active=true AND deleted_at IS NULL ORDER BY id LIMIT 1;
 IF admin_user_id IS NULL OR sam_organization_id IS NULL THEN RAISE EXCEPTION 'Existing admin and verified SAM organization required'; END IF;
INSERT INTO public.listings (public_listing_id, user_id, organization_id, created_by_user_id, published_by_user_id, property_type_code, usage_type, listing_type, listing_scope, title, description, sale_price, price_negotiable, land_area_sqm, contact_name, contact_phone, contact_email, line_id, show_phone, show_email, address_line1, address_line2, road, latitude, longitude, province_name, district_name, subdistrict_name, listing_status, moderation_status, approved_at, published_at, moderation_submitted_at, moderated_at, is_verified, is_active, source_channel, price_unit, slug) VALUES ('93c08330-cdd1-4be3-81b2-1d81cbb5b092', admin_user_id, sam_organization_id, admin_user_id, admin_user_id, 'land', 'residence', 'sale', 'land_plot', 'ขายตรง SAM ที่ดิน 12-1-82.6 ไร่ ติดถนนคู่ขนานมอเตอร์เวย์ บางบ่อ มีแนวโครงการคลองผ่าน', 'ที่ดินเปล่า 7 แปลงติดต่อกัน ตำบลบางพลีน้อย อำเภอบางบ่อ จังหวัดสมุทรปราการ ติดถนนคู่ขนานทางหลวงพิเศษหมายเลข 7 เนื้อที่รวม 12 ไร่ 1 งาน 82.6 ตร.ว. หรือ 4,982.6 ตร.ว. (19,930.4 ตร.ม.) ราคาเสนอขายจาก SAM 29,418,000 บาท ประมาณ 5,904 บาท/ตร.ว. รหัสทรัพย์ 3A0708

แปลงที่ดินมีรูปคล้ายสี่เหลี่ยมคางหมู ด้านทิศตะวันตกติดถนนหน้ากว้างประมาณ 76 เมตร ลึกสุดประมาณ 380 เมตร ระดับที่ดินต่ำกว่าถนนประมาณ 1 เมตร ถนนคู่ขนานหน้าทรัพย์เป็นทางสาธารณประโยชน์ ผิวลาดยางกว้างประมาณ 6 เมตร เขตทางประมาณ 10 เมตร ตามข้อมูล SAM

ข้อมูลสำคัญ: SAM ระบุว่ามีแนวโครงการคลองระบายน้ำหลากป่าสัก–อ่าวไทย ระยะที่ 1 ผ่านที่ตั้งทรัพย์บริเวณสะพานข้ามคลอง โดยเกี่ยวข้องกับโฉนด 27053 เต็มทั้งแปลง และโฉนด 27054 รวมเนื้อที่ตามหมายเหตุประมาณ 1 ไร่ 1 งาน 68.7 ตร.ว. (2,274.8 ตร.ม.) ต้องยืนยันแนวโครงการ ขอบเขตที่ได้รับผลกระทบ สถานะดำเนินการ สิทธิที่เกี่ยวข้อง และพื้นที่คงเหลือล่าสุดกับ SAM และหน่วยงานเจ้าของโครงการก่อนเสนอซื้อ

โฉนดที่ดินทั้งหมด 7 ฉบับ: 26361, 27053, 27054, 27055, 27056, 27057 และ 27058 ต้นทางระบุเขตผังเมืองสีเขียว อยู่ในย่านเกษตรกรรม และใช้ประโยชน์ทำนา พื้นที่รอบข้างเป็นนาข้าวและบ่อปลา ข้อมูลนี้เป็นการใช้ประโยชน์ตามต้นทาง ผู้สนใจควรตรวจข้อกำหนดการใช้ที่ดินตามแผนที่ผังเมืองปัจจุบันและลักษณะโครงการที่ต้องการพัฒนา

การเดินทาง: ใช้ถนนคู่ขนานมอเตอร์เวย์จากกรุงเทพฯ มุ่งหน้าอำเภอบางปะกง ข้ามคลองพระยานาคราช ผ่านบริเวณ กม.35 ก่อนถึงแยกถนนสายบ้านคลองพระยานาคประมาณ 850 เมตร ทรัพย์อยู่ด้านซ้ายมือ ใช้พิกัดที่ผู้ดูแลให้ 13.625667461799871, 100.91426422959044 ซึ่งอยู่ห่างจากหมุด SAM ประมาณ 6 เมตร หมุดใช้บอกตำแหน่งโดยประมาณ ไม่ใช่แนวเขตที่ดิน

หน้า SAM แสดงสถานะซื้อตรงและราคาประกาศขายข้างต้น ณ วันที่ 11 กันยายน 2569 ติดต่อฝ่ายขาย SAM โทร 02-686-1888 หรือ LINE @samline พร้อมแจ้งรหัส 3A0708 เพื่อยืนยันสถานะพร้อมขาย ราคา และเงื่อนไขล่าสุด

ภาพจริงจาก SAM แสดงวันที่ 12 มีนาคม 2564 พร้อมผังแปลง ภาพตำแหน่ง และแผนที่การเดินทาง ควรนัดดูสภาพปัจจุบันและตรวจระดับดิน การระบายน้ำ ทางเข้าออก และการใช้ประโยชน์จริงก่อนตัดสินใจ', 29418000, false, 19930.4, 'ฝ่ายขายและส่งเสริมกิจกรรมการขาย — SAM', '026861888', 'sales@sam.or.th', '@samline', true, true, 'ที่ดิน 7 แปลง ติดถนนคู่ขนานมอเตอร์เวย์ กม.35', 'ข้ามคลองพระยานาคราช มุ่งหน้าบางปะกง', 'ถนนคู่ขนานทางหลวงพิเศษหมายเลข 7', 13.625667461799871, 100.91426422959044, 'สมุทรปราการ', 'บางบ่อ', 'บางพลีน้อย', 'active', 'approved', now(), now(), now(), now(), true, true, 'editorial_import', 'total', 'sam-direct-sale-land-motorway-7-bang-phli-noi-3a0708') RETURNING id INTO property_listing_id;
