INSERT INTO public.listing_sources (listing_id, source_type, publisher_name, source_url, reference_code, captured_at, notes) VALUES (property_listing_id, 'editorial_import', 'บริษัท บริหารสินทรัพย์สุขุมวิท จำกัด (SAM)', 'https://www.sam.or.th/site/npa/detail.php?id=19382&keyref=6007623', '3A0708', now(), 'Official SAM page captured 2026-09-11. Seven adjoining agricultural land plots, direct purchase THB 29,418,000. Material canal project note retained in both languages and terms. The stated combined area for deeds 27053 and 27054 is recorded as source-reported, not independently surveyed. Eight original images retained with captions and dates; optimized WebP copies, no added watermark or visual retouching. Duplicate search included every listing status and deleted records, source code, page ID, keyref, title deeds, area and nearby coordinates; no matches before import. Import has a duplicate guard and advisory transaction lock.') ;
INSERT INTO public.listing_translations (listing_id, language_code, title, description, address_line1, address_line2, road, subdistrict_name, district_name, province_name, seo_title, seo_description, translation_status, translation_source, reviewed_at, search_text) VALUES (property_listing_id, 'en', 'SAM Direct Sale: 12 Rai Land by Motorway 7, Bang Bo, with Canal Project Corridor', 'Seven adjoining vacant land plots in Bang Phli Noi, Bang Bo, Samut Prakan, beside the Motorway 7 frontage road. Total area: 12 rai 1 ngan 82.6 sq.wah, equivalent to 4,982.6 sq.wah or 19,930.4 sq.m. SAM announced price: THB 29,418,000, approximately THB 5,904 per sq.wah. Asset reference: 3A0708.

The approximately trapezoidal site has 76 metres of western road frontage and a maximum depth of approximately 380 metres. Land is approximately one metre below the road. SAM describes the public asphalt frontage road as approximately six metres wide within a ten-metre right of way.

Material source note: the Pa Sak–Gulf of Thailand flood diversion canal project, Phase 1, crosses the property near a canal bridge. SAM names the entirety of title deed 27053 and deed 27054, with a stated combined area of approximately 1 rai 1 ngan 68.7 sq.wah (2,274.8 sq.m.). Confirm the project corridor, affected extent, current implementation stage, relevant rights and remaining area with SAM and the responsible authority before submitting an offer.

Seven title deeds: 26361, 27053, 27054, 27055, 27056, 27057 and 27058. SAM identifies green planning zoning, agricultural surroundings and rice cultivation on the land, with rice fields and fish ponds nearby. Confirm current planning provisions for any intended development.

Directions from Bangkok toward Bang Pakong follow the Motorway 7 frontage road across Khlong Phraya Nakkharat, past kilometre 35. The site is on the left approximately 850 metres before the Ban Khlong Phraya Nak road junction. Administrator coordinates are used, approximately six metres from the SAM pin; the pin is not a boundary survey.

SAM showed direct-purchase status and this announced price on 11 September 2026. Contact SAM Sales at 02-686-1888 or LINE @samline, quoting 3A0708, to confirm availability, current price and terms. Original property photos display 12 March 2021. Inspect current site conditions, land level, drainage, access and use.', 'Seven plots by Motorway 7 frontage road, km 35', 'Across Khlong Phraya Nakkharat toward Bang Pakong', 'Motorway 7 Frontage Road', 'Bang Phli Noi', 'Bang Bo', 'Samut Prakan', 'SAM Land by Motorway 7, Bang Bo — THB 29.418M', 'Seven plots, 12 rai 1 ngan 82.6 sq.wah, 76 m frontage. SAM 3A0708. A canal project corridor affects the site; see details and plans.', 'published', 'ai_assisted', now(), 'sam direct sale: 12 rai land by motorway 7, bang bo, with canal project corridor seven adjoining vacant land plots in bang phli noi, bang bo, samut prakan, beside the motorway 7 frontage road. total area: 12 rai 1 ngan 82.6 sq.wah, equivalent to 4,982.6 sq.wah or 19,930.4 sq.m. sam announced price: thb 29,418,000, approximately thb 5,904 per sq.wah. asset reference: 3a0708.

the approximately trapezoidal site has 76 metres of western road frontage and a maximum depth of approximately 380 metres. land is approximately one metre below the road. sam describes the public asphalt frontage road as approximately six metres wide within a ten-metre right of way.

material source note: the pa sak–gulf of thailand flood diversion canal project, phase 1, crosses the property near a canal bridge. sam names the entirety of title deed 27053 and deed 27054, with a stated combined area of approximately 1 rai 1 ngan 68.7 sq.wah (2,274.8 sq.m.). confirm the project corridor, affected extent, current implementation stage, relevant rights and remaining area with sam and the responsible authority before submitting an offer.

seven title deeds: 26361, 27053, 27054, 27055, 27056, 27057 and 27058. sam identifies green planning zoning, agricultural surroundings and rice cultivation on the land, with rice fields and fish ponds nearby. confirm current planning provisions for any intended development.

